<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,LearningTask,Employer,Programme};
use App\Support\{HelpCatalogue,DirectoryCatalog};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use PHPUnit\Framework\Attributes\TestWith;
use Tests\TestCase;
class Usability55Test extends TestCase {
 use LazilyRefreshDatabase;
 private function u(string$role='admin'):User{return User::factory()->create(['role'=>$role]);}
 private function a(User$u):Apprentice{return Apprentice::factory()->create(match($u->role){'tutor'=>['tutor_id'=>$u->id],'apprentice'=>['user_id'=>$u->id],default=>[]});}
 #[TestWith(['employers','employer'])] #[TestWith(['programmes','programme'])] #[TestWith(['groups','tutor group'])] #[TestWith(['staff','staff member'])]
 public function test_directory_actions_name_the_actual_record(string$kind,string$noun):void{$this->actingAs($this->u())->get('/directories/'.$kind)->assertOk()->assertSee($kind==='employers'?'Add or link employer':'Add '.$noun);$this->get('/directories/'.$kind.'/create')->assertOk()->assertSee($kind==='employers'?'Add or link employer':'Add '.$noun)->assertSee($kind==='employers'?'Create employer':'Save '.$noun);$this->assertSame($noun,DirectoryCatalog::singular($kind));}
 #[TestWith(['admin'])] #[TestWith(['ceo'])] #[TestWith(['tutor'])] #[TestWith(['apprentice'])]
 public function test_zero_filtered_tasks_keep_the_real_allocation_and_do_not_offer_duplicate_allocation(string$role):void{$u=$this->u($role);$a=$this->a($u);LearningTask::factory()->create(['apprentice_id'=>$a->id,'status'=>'Draft']);$before=[LearningTask::count(),DB::table('learning_events')->count()];$this->actingAs($u)->get('/apprentices/'.$a->id.'/learning?status=Approved')->assertOk()->assertSee('No matching tasks')->assertSee('1 task(s) are already assigned')->assertSee('Show all assigned tasks')->assertDontSee('No tasks assigned')->assertDontSee('name="confirmed"',false)->assertSee('0 of 1 tasks approved');$this->assertSame($before,[LearningTask::count(),DB::table('learning_events')->count()]);}
 public function test_true_empty_supported_programme_still_allows_only_explicit_task_allocation():void{$u=$this->u();$a=$this->a($u);$p=Programme::where('standard_code','ST0499')->where('version','1.3')->first()??Programme::factory()->create(['standard_code'=>'ST0499','version'=>'1.3','active'=>true]);$a->programme_id=$p->id;$a->save();$this->actingAs($u)->get('/apprentices/'.$a->id.'/learning')->assertOk()->assertSee('No tasks assigned')->assertSee('name="confirmed"',false)->assertSee('Preview this task catalogue');$this->assertDatabaseCount('learning_tasks',0);}
 public function test_true_empty_learner_gets_help_instead_of_admin_assignment_controls():void{$u=$this->u('apprentice');$a=$this->a($u);$this->actingAs($u)->get('/apprentices/'.$a->id.'/learning')->assertOk()->assertSee('Ask your Tutor to check')->assertDontSee('Check the programme link')->assertDontSee('name="confirmed"',false);}
 public function test_unlinked_admin_record_has_a_real_programme_correction_route():void{$u=$this->u();$a=$this->a($u);$a->programme_id=null;$a->save();$this->actingAs($u)->get('/apprentices/'.$a->id.'/learning')->assertOk()->assertSee('Check the programme link')->assertSee(route('apprentices.edit',$a),false);$this->assertDatabaseCount('learning_tasks',0);}
 public function test_empty_directory_search_prompts_existing_record_check_instead_of_new_duplicate():void{$u=$this->u();Employer::factory()->create(['name'=>'Existing workshop']);$this->actingAs($u)->get('/directories/employers?search=NoSuchEmployer55')->assertOk()->assertSee('No matching records in this search or status filter')->assertSee('Clear filters and check existing records')->assertDontSee('Add your first employer');}
 public function test_empty_directory_state_filter_is_not_treated_as_a_missing_directory():void{$u=$this->u();$this->actingAs($u)->get('/directories/employers?state=inactive&search=NoSuchEmployer55')->assertOk()->assertSee('Clear filters and check existing records')->assertDontSee('Add your first employer');}
 public function test_saved_employer_explains_organisation_contact_and_named_account_separation():void{$u=$this->u();$this->actingAs($u)->post('/directories/employers',['reference'=>'EMP55','name'=>'Fictional workshop55','active'=>1])->assertRedirect();$e=Employer::where('reference','EMP55')->firstOrFail();$before=User::count();$this->get('/directories/employers/'.$e->id)->assertOk()->assertSee('What to do next')->assertSee('Set up named employer contacts')->assertSee('does not create a personal login');$this->assertSame($before,User::count());$this->assertDatabaseCount('employer_apprentice_grants',0);}
 public function test_saved_staff_has_assignment_next_step_without_an_invitation():void{$u=$this->u();$s=$this->u('tutor');$this->actingAs($u)->get('/directories/staff/'.$s->id)->assertOk()->assertSee('Assign staff on an apprentice')->assertSee('Use Staff onboarding for a sign-in invitation.');$this->assertDatabaseCount('account_onboarding_tokens',0);}
 public function test_apprentice_identity_precedes_actions_and_admin_setup_steps_are_explicit():void{$u=$this->u();$a=$this->a($u);$r=$this->actingAs($u)->get('/apprentices/'.$a->id);$r->assertOk()->assertSee('More record options')->assertSee('Edit apprentice')->assertSee('Set up apprentice sign-in');$s=$r->getContent();$this->assertLessThan(strpos($s,'Common apprentice actions'),strpos($s,'<h1>'));$this->get('/apprentices/create')->assertOk()->assertSee('Missing employer, programme, group or staff choices?');}
 public function test_tutor_next_steps_do_not_expose_account_setup_or_profile_edit():void{$u=$this->u('tutor');$a=$this->a($u);$this->actingAs($u)->get('/apprentices/'.$a->id)->assertOk()->assertSee('Open training tasks')->assertDontSee(route('apprentices.edit',$a),false)->assertDontSee('Set up apprentice sign-in')->assertDontSee('Check details and assignments');}
 public function test_apprentice_next_steps_are_personal_and_do_not_expose_admin_setup():void{$u=$this->u('apprentice');$a=$this->a($u);$this->actingAs($u)->get('/apprentices/'.$a->id)->assertOk()->assertSee('My training tasks')->assertDontSee('Set up apprentice sign-in')->assertDontSee('Check details and assignments');}
 public function test_referral_feedback_is_visible_before_editing_and_escaped():void{$u=$this->u('apprentice');$a=$this->a($u);$t=LearningTask::factory()->create(['apprentice_id'=>$a->id,'status'=>'Referred','submissions'=>[['version'=>1,'submitted_at'=>now()->toIso8601String(),'answers'=>[],'decision'=>['status'=>'Referred','feedback'=>'FIRST-OLD55','date'=>'2026-11-01','tutor_name'=>'Fictional Tutor','source_fields'=>[]]],['version'=>2,'submitted_at'=>now()->toIso8601String(),'answers'=>[],'decision'=>['status'=>'Referred','feedback'=>'Correct the tyre reading <script>bad55</script>','date'=>'2026-11-02','tutor_name'=>'Fictional Tutor','source_fields'=>[]]]]]);$r=$this->actingAs($u)->get('/tasks/'.$t->id);$r->assertOk()->assertSee('Most recent referral feedback')->assertSee('Correct the tyre reading <script>bad55</script>')->assertDontSee('<script>bad55</script>',false)->assertSee('Submit to tutor');$s=$r->getContent();$this->assertLessThan(strpos($s,'<h2>Apprentice work'),strpos($s,'Most recent referral feedback'));$this->assertSame('Referred',$t->fresh()->status);}
 public function test_submitted_work_stays_locked_and_has_a_clear_waiting_message():void{$u=$this->u('apprentice');$a=$this->a($u);$t=LearningTask::factory()->create(['apprentice_id'=>$a->id,'status'=>'Awaiting marking','submitted_at'=>now()]);$this->actingAs($u)->get('/tasks/'.$t->id)->assertOk()->assertSee('awaiting a Tutor decision')->assertDontSee('>Submit to tutor<',false)->assertDontSee('>Add evidence<',false);$this->assertSame('Awaiting marking',$t->fresh()->status);}
 public function test_out_of_scope_people_and_tasks_still_refuse_access():void{$u=$this->u('tutor');$a=Apprentice::factory()->create();$t=LearningTask::factory()->create(['apprentice_id'=>$a->id]);$this->actingAs($u)->get('/apprentices/'.$a->id)->assertForbidden();$this->get('/tasks/'.$t->id)->assertForbidden();}
 #[TestWith(['/apprentices/create','Add and reopen an apprentice'])] #[TestWith(['/directories/employers','Set up an employer organisation and named contact'])] #[TestWith(['/employer-accounts','Set up an employer organisation and named contact'])] #[TestWith(['/marking','Mark work and register attendance'])]
 public function test_help_is_available_without_repeating_the_workflow_note(string$url,string$title):void{$u=$this->u();$this->actingAs($u)->get($url)->assertOk()->assertSee(route('help.index'))->assertDontSee('Help with this page:');$context=HelpCatalogue::context($u,request());$this->assertNotNull($context);$this->get(route('help.index',['guide'=>$context['id']]))->assertOk()->assertSee($title);}
 public function test_employer_setup_guide_is_not_disclosed_to_an_apprentice():void{$u=$this->u('apprentice');$this->actingAs($u)->get('/help?guide=employer-setup')->assertNotFound();$this->assertArrayNotHasKey('employer-setup',HelpCatalogue::visible($u));}
 public function test_catalogue_has_the_new_and_updated_guides_and_all_live_destinations_resolve():void{$guides=HelpCatalogue::all();$this->assertCount(43,$guides);$this->assertStringContainsString('Show all assigned tasks',$guides['submit-work']['body']);$this->assertStringContainsString('Check existing records',$guides['setup']['body']);$this->assertSame(['manager'],$guides['employer-setup']['audience']);}
 public function test_review_stages_explain_frozen_source_without_creating_a_draft():void{$u=$this->u();$a=$this->a($u);$this->actingAs($u)->get(route('reviews.create',$a))->assertOk()->assertSee('How signing works')->assertSee('Ready for signatures freezes the checked source')->assertSee('independent staff check follows');$this->assertDatabaseCount('progress_review_drafts',0);}

 public function test_read_only_release_reports_do_not_describe_annual_or_usability_work_as_theme_only():void{$r=\App\Support\Release55Check::report();$this->assertSame('55',$r['pack']);$this->assertFalse($r['theme_only']);$this->assertFalse($r['actual_target_acceptance']);$this->assertFalse($r['writes_performed']);$this->assertNotSame('needs_attention',$r['status']);$this->assertFalse(\App\Support\Release54Check::report()['theme_only']);$this->assertTrue(\App\Support\Release53Check::report()['theme_only']);$this->artisan('gta:release-check55')->assertExitCode(0);}

}
